const S={tab:0};let cur='dash',charts=[],TB={};
function bdg(s){const c=/^(Active|Verified|Completed|Success|Paid|Approved|Resolved|Sent|Confirmed|None|Yes)$/.test(s)?'g':/^(Pending|Under review|Rescheduled|Open|Scheduled|Processing)$/.test(s)?'a':/^(Blocked|Failed|Rejected|Cancelled|Suspended|Disputed|Frozen)$/.test(s)?'r':'n';return `<span class="bd ${c}">${s}</span>`}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;$('#toasts').append(t);setTimeout(()=>t.remove(),3200)}
function modal(html){const o=document.createElement('div');o.className='ov';o.innerHTML=`<div class="md" role="dialog">${html}</div>`;o.onclick=e=>{if(e.target==o)o.remove()};document.body.append(o);lucide.createIcons();return o}
function confirmD(msg,fn){const o=modal(`<h3>Please confirm</h3><p>${msg}</p><div class="row"><button class="btn o" id="cn">Cancel</button><button class="btn" id="cy">Confirm</button></div>`);o.querySelector('#cn').onclick=()=>o.remove();o.querySelector('#cy').onclick=()=>{o.remove();fn()}}
function form(title,fields,save,btn='Save'){const h=fields.map((f,i)=>`<div class="fld"><label>${f.l}</label>${f.o?`<select name="${i}">${f.o.map(x=>`<option ${x==f.v?'selected':''}>${x}</option>`).join('')}</select>`:f.t=='area'?`<textarea name="${i}" rows="3">${f.v??''}</textarea>`:`<input name="${i}" type="${f.t||'text'}" value="${f.v??''}">`}<div class="er"></div></div>`).join('');
const o=modal(`<h3>${title}</h3>${h}<div class="row"><button class="btn o" id="cn">Cancel</button><button class="btn" id="sv">${btn}</button></div>`);
o.querySelector('#cn').onclick=()=>o.remove();o.querySelector('#sv').onclick=()=>{let ok=true;const vals=fields.map((f,i)=>{const el=o.querySelector(`[name="${i}"]`),v=el.value.trim(),er=el.parentElement.querySelector('.er');er.textContent='';if(f.req!==false&&!v){er.textContent=`${f.l} is required`;ok=false}else if(f.t=='number'&&v&&(isNaN(v)||+v<0)){er.textContent='Enter a valid positive number';ok=false}return f.t=='number'?+v:v});if(ok){o.remove();save(vals)}}}
function tabs(n){return `<div class="tabs">${n.map((x,i)=>`<button class="tab ${S.tab==i?'on':''}" onclick="S.tab=${i};go(cur,1)">${x}</button>`).join('')}</div>`}
function stat(ic,v,l){return `<div class="card stat"><div class="ic"><i data-lucide="${ic}"></i></div><div><b>${v}</b><span>${l}</span></div></div>`}
function kv(a){return a.map(x=>`<div class="kv"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
/* generic searchable/filterable table. acts: [[label,fn(row,i)]] */
function T(id,cols,rows,o={}){TB[id]={cols,rows,o,q:'',f:''};const st=o.st>=0&&o.st!=null?[...new Set(rows.map(r=>r[o.st]))]:[];
return `<div class="bar"><input placeholder="Search…" oninput="TB['${id}'].q=this.value.toLowerCase();tb('${id}')" aria-label="Search">${st.length?`<select onchange="TB['${id}'].f=this.value;tb('${id}')"><option value="">All status</option>${st.map(s=>`<option>${s}</option>`).join('')}</select>`:''}<span style="flex:1"></span>${o.add?`<button class="btn" onclick="${o.add[1]}()"><i data-lucide="plus"></i>${o.add[0]}</button>`:''}</div><div class="card tw" style="padding:6px"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}${o.acts?'<th></th>':''}</tr></thead><tbody id="tb_${id}">${body(id)}</tbody></table></div>`}
function body(id){const {cols,rows,o,q,f}=TB[id];const out=rows.map((r,i)=>[r,i]).filter(([r])=>(!q||r.join(' ').toLowerCase().includes(q))&&(!f||r[o.st]==f));if(!out.length)return `<tr><td colspan="${cols.length+1}" style="text-align:center;color:var(--mu);padding:26px">No matching records. Clear the search or filter.</td></tr>`;
return out.map(([r,i])=>`<tr>${r.map((v,j)=>`<td>${j==o.st?bdg(v):o.fmt&&o.fmt[j]?o.fmt[j](v):v}</td>`).join('')}${o.acts?`<td><details class="dd"><summary>Actions</summary><div>${o.acts.map((a,k)=>`<button onclick="this.closest('details').open=false;TB['${id}'].o.acts[${k}][1](TB['${id}'].rows[${i}],${i})">${a[0]}</button>`).join('')}</div></details></td>`:''}</tr>`).join('')}
function tb(id){$('#tb_'+id).innerHTML=body(id);lucide.createIcons()}
function chart(id,type,labels,ds,extra={}){const c=document.getElementById(id);if(!c)return;if(typeof Chart==='undefined'){c.parentElement.innerHTML='<small style="color:var(--mu)">Chart library could not load (check internet connection).</small>';return}charts.push(new Chart(c,{type,data:{labels,datasets:ds.map((d,i)=>({borderColor:['#087E83','#f2a33a','#4f6bed'][i],backgroundColor:type=='line'?['#087E8322','#f2a33a22'][i]:['#087E83','#f2a33a','#4f6bed','#d64545'][type=='doughnut'?0:i],fill:type=='line',tension:.35,borderRadius:6,...d}))},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:ds.length>1||type=='doughnut',position:'bottom'}},...extra}}))}
const MO=['May','Jun','Jul','Aug','Sep','Oct'];
