function calc(){const t=+$('#ct').value||0,s=+$('#cs').value||0;$('#co').innerHTML=kv([['Consultation',num(t)+' tokens'],['Doctor share ('+s+'%)',num(Math.round(t*s/100))+' tokens'],['CareX share ('+(100-s)+'%)',num(Math.round(t*(100-s)/100))+' tokens'],['Doctor payout value',inr(Math.round(t*s/100*.1))],['CareX commission value',inr(Math.round(t*(100-s)/100*.1))]])}
