<div class="card"><h3>Commission calculator</h3><div class="bar"><input id="ct" type="number" value="500" oninput="calc()"><select id="cs" onchange="calc()"><option>80</option><option>85</option><option>75</option></select></div><div id="co"></div><small style="color:var(--mu)">Demo rate: 10 tokens ≈ ₹1. Applies only after settlement.</small></div></div>
