P.purchases=()=>`<div class="note">Every successful top-up is recorded against the customer wallet ledger. Email values below are fictional demo data; production records must come from verified user profiles and gateway webhooks.</div><div class="grid g5 mb">${stat('receipt','7','Purchase records')+stat('indian-rupee','₹1,745','Gross successful top-ups')+stat('coins','22,100','Tokens credited')+stat('clock','1','Pending transaction')+stat('x-circle','1','Failed transaction')}</div>`+T('purch',['Transaction ID','User ID','Customer','Email ID','Amount (₹)','Tokens','Gateway / ledger ref','Date & time','Status'],D.txns.map((t,i)=>[t[0],D.users.find(u=>u[1]==t[1])?.[0]||'U-—',t[1],purchaseEmails[t[1]]||'—',t[3],t[4],t[5],['30 Oct 2026, 09:41','30 Oct 2026, 09:36','30 Oct 2026, 09:20','29 Oct 2026, 16:40','29 Oct 2026, 15:10','29 Oct 2026, 12:05','28 Oct 2026, 18:22'][i],t[6]]),{st:8,fmt:{4:inr,5:num}});
const doctorStats=[['D-201','Dr. Kavita Menon','4.8',14,286,274,12,8200,6200,8],['D-202','Dr. Suresh Reddy','4.6',9,198,190,8,5400,3600,5],['D-203','Dr. Priya Banerjee','—',6,42,38,4,1200,0,0],['D-204','Dr. Anil Kapoor','4.9',18,342,335,7,9600,7200,9],['D-205','Dr. Nisha Joseph','4.2',11,176,151,25,4300,2100,3],['D-206','Dr. Rahul Desai','—',8,64,58,6,1800,0,0],['D-207','Dr. Sameer Qureshi','4.7',12,231,220,11,6800,4200,7]];
function perfScore(r){let rating=r[2]=='—'?0:Number(r[2])/5*35,completion=r[4]?r[5]/r[4]*30:0,tenure=Math.min(r[3]/18,1)*10,volume=Math.min(r[4]/300,1)*15,complaints=Math.max(0,10-r[6]*2);return Math.round(rating+completion+tenure+volume+complaints)}
function perfFactor(score){return score>=90?1:score>=80?.9:score>=70?.8:score>=60?.65:.5}
let tokenRate=0.8;
P.performance=()=>`<div class="note">Illustrative performance score: rating (35%), completed-consultation rate (30%), tenure (10%), customer volume (15%) and complaint record (10%). Score guides payout eligibility/rate; owner reviews every claim. These demo weights are configurable product policy, not clinical quality certification.</div><div class="grid g5 mb">${stat('star','4.7','Average doctor rating')+stat('users',num(doctorStats.reduce((a,r)=>a+r[4],0)),'Customers handled')+stat('calendar-check',num(doctorStats.reduce((a,r)=>a+r[5],0)),'Completed consultations')+stat('shield-alert',num(doctorStats.reduce((a,r)=>a+r[6],0)),'Recorded complaints')+stat('coins',num(doctorStats.reduce((a,r)=>a+r[7],0)),'Unclaimed earned tokens')}</div><div class="card tw"><table><thead><tr><th>Doctor</th><th>Active tenure</th><th>Customers</th><th>Completed</th><th>Rating</th><th>Complaints</th><th>Score / 100</th><th>Payout factor</th><th>Unclaimed tokens</th><th>Eligible estimate (₹)</th></tr></thead><tbody>${doctorStats.map(r=>{let sc=perfScore(r),factor=perfFactor(sc);return `<tr><td><b>${r[1]}</b><small style="display:block;color:var(--mu)">${r[0]}</small></td><td>${r[3]} months</td><td>${r[4]}</td><td>${r[5]}</td><td>${r[2]}</td><td>${r[6]}</td><td><b>${sc}</b></td><td>${Math.round(factor*100)}%</td><td>${num(r[7]-r[8])}</td><td>${inr((r[7]-r[8])*tokenRate*factor)}</td></tr>`}).join('')}</tbody></table></div><div class="note" style="margin-top:12px">Payout estimate uses unclaimed tokens × owner-configured ₹/token rate × performance factor. Final payable amount is subject to settled consultations, dispute holds, tax/withholding rules and owner approval.</div>`;
let payoutClaims=[['CL-1501','D-201','Dr. Kavita Menon',6200,'28 Oct 2026','Pending'],['CL-1502','D-202','Dr. Suresh Reddy',3600,'27 Oct 2026','Pending'],['CL-1503','D-204','Dr. Anil Kapoor',7200,'26 Oct 2026','Approved'],['CL-1504','D-207','Dr. Sameer Qureshi',4200,'25 Oct 2026','Paid']];
function claimAction(i,action){let r=payoutClaims[i];if(r[5]!='Pending')return toast('Only pending claims can be reviewed');let ds=doctorStats.find(x=>x[0]==r[1]),factor=perfFactor(perfScore(ds)),amount=Math.round(r[3]*tokenRate*factor);if(action=='approve'&&D.ds.some(d=>d[2].includes(r[2])&&d[4]!='Resolved'))return toast('Hold: unresolved doctor dispute exists');form(`${action=='approve'?'Approve':'Reject'} ${r[0]}`,[{l:'Claimed tokens',v:r[3],t:'number'},{l:'Performance-adjusted payout (₹)',v:amount,t:'number'},{l:'Owner remark',t:'area'}],v=>{r[5]=action=='approve'?'Approved':'Rejected';if(action=='approve')r.push(v[1]);D.logs.unshift(['30 Oct 2026 now','Platform Owner',`${action}d token claim ${r[0]}`,'Payouts']);toast('Claim '+action+'d; audit entry added');go('payouts')},action=='approve'?'Approve claim':'Reject claim')}
P.payouts=()=>`<div class="note"><b>15-day payout cycle.</b> Doctors submit token claims from earned, settled consultations. Owner reviews performance and disputes, approves a rupee amount using the configurable conversion rate, then records the actual payment/UTR. This demo does not initiate a bank transfer.</div><div class="grid g5 mb">${stat('calendar-days','15 days','Payout cycle')+stat('coins',num(payoutClaims.filter(x=>x[5]=='Pending').reduce((a,x)=>a+x[3],0)),'Tokens awaiting review')+stat('banknote',inr(payoutClaims.filter(x=>x[5]=='Pending').reduce((a,x)=>{let d=doctorStats.find(z=>z[0]==x[1]);return a+x[3]*tokenRate*perfFactor(perfScore(d))},0)),'Estimated pending payout')+stat('check-circle',payoutClaims.filter(x=>x[5]=='Paid').length,'Paid claims')+stat('clock','Every 1st & 16th','Suggested review dates')}</div><div class="card mb"><h3>Owner payout configuration</h3><div class="bar"><label>Base conversion rate (₹ per doctor token)</label><input id="rate" type="number" min="0.01" step="0.01" value="${tokenRate}" style="width:120px"><button class="btn" onclick="let v=Number(document.getElementById('rate').value);if(!v||v<0){toast('Enter a valid rate');return}tokenRate=v;toast('Conversion rate updated for this demo');go('payouts')">Save rate</button></div><small style="color:var(--mu)">Performance factor: 90+ = 100%, 80–89 = 90%, 70–79 = 80%, 60–69 = 65%, below 60 = 50%. Illustrative defaults; confirm policy before launch.</small></div>`+T('claims',['Claim ID','Doctor ID','Doctor','Tokens claimed','Claim date','Status','Actions'],payoutClaims,{st:5,acts:[['View performance',r=>go('performance')],['Approve', (r,i)=>claimAction(i,'approve')],['Reject',(r,i)=>claimAction(i,'reject')],['Mark paid',(r,i)=>{if(r[5]!='Approved')return toast('Approve claim first');form('Record payout',[{l:'Paid amount (₹)',t:'number',v:r[7]||Math.round(r[3]*tokenRate)},{l:'Bank UTR / transaction reference'},{l:'Payment date'}],v=>{r[5]='Paid';r.push(v[0],v[1],v[2]);D.logs.unshift(['30 Oct 2026 now','Platform Owner','Recorded payout for '+r[0],'Payouts']);toast('Payment recorded with reference');go('payouts')})}]]});


/* ---------- complaint & grievance resolution ---------- */
let complaintRows=[
 {id:'CMP-1001',user:'Ananya Rao',uid:'U-1001',doctor:'Dr. Kavita Menon',did:'D-201',booking:'BK-50021',category:'Unprofessional behaviour',desc:'Demo complaint: user reports that the doctor ended the consultation early.',tokens:600,when:'30 Oct 2026, 10:45',status:'New',decision:'',reason:'',staff:'Unassigned',penalty:0},
 {id:'CMP-1002',user:'Arjun Mehta',uid:'U-1006',doctor:'Dr. Sameer Qureshi',did:'D-207',booking:'BK-50015',category:'Appointment not delivered',desc:'Demo complaint: consultation connection issue; evidence needs review.',tokens:700,when:'28 Oct 2026, 19:05',status:'Under Review',decision:'',reason:'',staff:'Karan Malhotra',penalty:0},
 {id:'CMP-1003',user:'Sneha Patil',uid:'U-1005',doctor:'Dr. Nisha Joseph',did:'D-205',booking:'BK-50017',category:'Wrong fee / service',desc:'Demo complaint: user disputes the amount charged.',tokens:550,when:'29 Oct 2026, 09:40',status:'Resolved',decision:'Valid',reason:'Demo: doctor unavailable; reverse disputed appointment tokens.',staff:'Pooja Shah',penalty:0}
];
let complaintLedger=[['LED-C-001','CMP-1003','U-1005','User token reversal',550,'Credited','Demo entry']];
function complaintDetails(c){return `<h3>${c.id} · ${c.category}</h3>${kv([['User',c.user+' ('+c.uid+')'],['Doctor',c.doctor+' ('+c.did+')'],['Appointment',c.booking],['Appointment tokens',num(c.tokens)],['Submitted',c.when],['Status',c.status],['Assigned staff',c.staff],['Decision',c.decision||'Pending'],['Decision reason',c.reason||'—']])}<h4 style="margin:14px 0 6px">User statement</h4><p>${c.desc}</p><div class="note">Demo evidence placeholder: production system should securely store user attachments, appointment/chat records and doctor response.</div><div class="row"><button class="btn o" onclick="this.closest('.ov').remove()">Close</button></div>`}
function resolveComplaint(i){let c=complaintRows[i];if(c.status=='Resolved'||c.status=='Closed')return toast('This complaint is already closed');form('Staff investigation · '+c.id,[{l:'Assigned staff',v:c.staff=='Unassigned'?'':c.staff},{l:'Decision',o:['Valid — doctor/service issue verified','Invalid — knowingly false complaint verified','Inconclusive — insufficient evidence']},{l:'Investigation notes / reason',t:'area'},{l:'User penalty tokens (only if knowingly false; optional)',t:'number',v:0,req:false}],v=>{let decision=v[1].startsWith('Valid')?'Valid':v[1].startsWith('Invalid')?'Invalid':'Inconclusive',pen=Math.max(0,Number(v[3])||0);if(decision!='Invalid'&&pen>0)return toast('Penalty is only allowed for a verified knowingly false complaint');if(decision=='Invalid'&&pen>Math.max(0,(D.users.find(u=>u[0]==c.uid)?.[4]||0)))return toast('Penalty exceeds available demo wallet balance');c.staff=v[0]||'Owner Staff';c.decision=decision;c.reason=v[2];c.status=decision=='Inconclusive'?'Further Review':'Resolved';c.penalty=pen;
 if(decision=='Valid'){let u=D.users.find(x=>x[0]==c.uid);if(u)u[4]+=c.tokens;complaintLedger.unshift(['LED-'+Date.now(),' '+c.id,c.uid,'User token reversal',c.tokens,'Credited','Verified valid complaint']);let d=doctorStats.find(x=>x[0]==c.did);if(d)d[7]=Math.max(0,d[7]-c.tokens);D.logs.unshift(['30 Oct 2026 now',c.staff,'Verified complaint '+c.id+'; reversed '+c.tokens+' tokens','Complaints']);toast('Valid complaint: demo tokens reversed to user wallet');}
 else if(decision=='Invalid'){let u=D.users.find(x=>x[0]==c.uid);if(pen>0&&u)u[4]-=pen;if(pen>0)complaintLedger.unshift(['LED-'+Date.now(),c.id,c.uid,'False complaint policy penalty',-pen,'Recorded in platform penalty ledger','Never routed to personal wallet']);D.logs.unshift(['30 Oct 2026 now',c.staff,'Marked complaint '+c.id+' invalid; penalty '+pen,'Complaints']);toast('Decision recorded; penalty ledger updated');}
 else {D.logs.unshift(['30 Oct 2026 now',c.staff,'Marked complaint '+c.id+' inconclusive; no penalty','Complaints']);toast('Further review required; no tokens deducted');}go('complaints')},'Save investigation decision')}
P.complaints=()=>`<div class="note"><b>Complaint policy:</b> staff investigate evidence and request the doctor's response before deciding. A valid complaint reverses the disputed appointment tokens to the user. A penalty is permitted only when a knowingly false complaint is established under a published policy; an unproven complaint is not automatically false. Penalties are recorded in a separate CareX platform ledger, never a staff member's or owner's personal wallet. Demo actions update only this browser session.</div><div class="grid g5 mb">${stat('inbox',complaintRows.length,'Total complaints')+stat('clock',complaintRows.filter(c=>c.status=='New'||c.status=='Under Review').length,'Awaiting investigation')+stat('check-circle',complaintRows.filter(c=>c.decision=='Valid').length,'Valid complaints')+stat('shield-alert',complaintRows.filter(c=>c.decision=='Invalid').length,'Verified false complaints')+stat('coins',num(complaintLedger.filter(x=>x[3]=='User token reversal').reduce((a,x)=>a+x[4],0)),'Tokens reversed to users')}</div><div class="card mb"><h3>Investigation workflow</h3><p>1. Receive complaint → 2. Review appointment, chat and evidence → 3. Request doctor response → 4. Staff records reasoned decision → 5. Apply eligible token adjustment → 6. Keep audit trail and appeal route.</p></div>`+T('complaintTable',['Complaint ID','User','Doctor','Appointment','Category','Tokens','Submitted','Status'],complaintRows.map(c=>[c.id,c.user,c.doctor,c.booking,c.category,num(c.tokens),c.when,c.status]),{st:7,acts:[['View details',(r,i)=>modal(complaintDetails(complaintRows[i]))],['Investigate / decide',(r,i)=>resolveComplaint(i)],['Request doctor response',(r,i)=>{complaintRows[i].status='Waiting for Doctor';toast('Doctor response requested (demo)');go('complaints')}],['Reopen for appeal',(r,i)=>{complaintRows[i].status='Under Review';complaintRows[i].decision='';toast('Complaint reopened for review');go('complaints')}]]})+`<h3 style="margin:20px 0 10px">Complaint token adjustment ledger</h3>`+T('complaintLedger',['Ledger ref','Complaint','User ID','Entry type','Token change','Status','Note'],complaintLedger,{fmt:{4:v=>num(v)}});

/* ---------- router ---------- */
function go(id,keep){if(!keep){S.tab=0;document.querySelector('#sb').classList.remove('open')}cur=id;charts.forEach(c=>c.destroy());charts=[];TB={};$('#view').innerHTML=P[id]();NAV.flat().forEach(()=>{});$('#ttl').textContent=NAV.flatMap(g=>g[1]).find(x=>x[0]==id)[1];document.querySelectorAll('.ni').forEach(b=>b.classList.toggle('on',b.dataset.id==id));lucide.createIcons();if(id=='comm')calc();if(!keep)scrollTo(0,0)}
$('#nav').innerHTML=NAV.map(g=>`<div class="ng">${g[0]}</div>`+g[1].map(i=>`<button class="ni" data-id="${i[0]}" onclick="go('${i[0]}')"><i data-lucide="${i[2]}"></i>${i[1]}</button>`).join('')).join('');
$('#menu').onclick=()=>$('#sb').classList.toggle('open');
document.addEventListener('click',e=>{document.querySelectorAll('details.dd[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});
go('dash');
